#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    vector<int> v(n);
    for (int i = 0; i < n; i++) scanf("%d", &v[i]);

    // Compress the sequence into runs of equal values
    vector<pair<int,int>> runs; // (value, length)
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && v[j] == v[i]) j++;
        runs.push_back({v[i], j - i});
        i = j;
    }
    int m = (int)runs.size();

    // List of distinct values
    vector<int> vals;
    for (auto &p : runs) vals.push_back(p.first);
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    int k = (int)vals.size();

    int ans = 1; // at least one element can always be marked (n >= 1)

    // For every pair of distinct values (a, b), greedily pick runs of a/b
    // in an alternating fashion. Greedy is optimal: whenever the current run
    // has a value different from the last taken one, taking it never hurts.
    for (int x = 0; x < k; x++) {
        for (int y = x + 1; y < k; y++) {
            int a = vals[x], b = vals[y];
            int last = 0; // 0 is not a valid value (values >= 1)
            int cnt = 0;
            for (int i = 0; i < m; i++) {
                int val = runs[i].first;
                if ((val == a || val == b) && val != last) {
                    cnt += runs[i].second;
                    last = val;
                }
            }
            if (cnt > ans) ans = cnt;
        }
    }

    printf("%d\n", ans);
    return 0;
}
